import{c as e,Q as d,j as o,m as a}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"Claude Opus 5 完整指南","description":"","frontmatter":{},"headers":[],"relativePath":"research/best-practices/44-claude-opus-5.md","filePath":"research/best-practices/44-claude-opus-5.md","lastUpdated":1785909234000}'),r={name:"research/best-practices/44-claude-opus-5.md"};function l(s,t,n,c,u,i){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="claude-opus-5-完整指南" tabindex="-1">Claude Opus 5 完整指南 <a class="header-anchor" href="#claude-opus-5-完整指南" aria-label="Permalink to &quot;Claude Opus 5 完整指南&quot;">​</a></h1><blockquote><p>來源：<a href="https://www.anthropic.com/news/claude-opus-5" target="_blank" rel="noreferrer">Introducing Claude Opus 5</a>（2026-07-24） 來源：Claude Code changelog v2.1.219（<code>claude-opus-5</code>，1M context window） 整理日期：2026-08-04</p></blockquote><hr><h2 id="模型定位" tabindex="-1">模型定位 <a class="header-anchor" href="#模型定位" aria-label="Permalink to &quot;模型定位&quot;">​</a></h2><p><strong>Claude Opus 5</strong> 於 2026-07-24 發布，是 Claude 5 世代不到兩個月內的第四個模型（Fable 5 → Mythos 5 → Sonnet 5 → Opus 5）。定位是「多數任務逼近 Fable 5、價格只有一半」的日常主力：接手 Opus 4.8 的價位帶與角色，成為 <strong>Claude Max 的預設模型</strong>、<strong>Claude Pro 可用的最強模型</strong>。</p><hr><h2 id="技術規格" tabindex="-1">技術規格 <a class="header-anchor" href="#技術規格" aria-label="Permalink to &quot;技術規格&quot;">​</a></h2><table tabindex="0"><thead><tr><th>規格</th><th>值</th></tr></thead><tbody><tr><td>Model ID</td><td><code>claude-opus-5</code></td></tr><tr><td>Context window</td><td><strong>1M token</strong>（changelog v2.1.219）</td></tr><tr><td>輸入定價</td><td>$5 / MTok（與 Opus 4.8 同價）</td></tr><tr><td>輸出定價</td><td>$25 / MTok（與 Opus 4.8 同價）</td></tr><tr><td>Fast mode</td><td>約 2.5× 速度、2× 價格（$10 / $50）</td></tr><tr><td>Effort 等級</td><td>low / medium / high 可調，換取速度與成本</td></tr><tr><td>發布日期</td><td>2026-07-24</td></tr></tbody></table><p><strong>可用範圍</strong>：Claude API、Claude Code、Claude Cowork、Claude Platform、claude.ai；AWS Bedrock / Google Cloud Vertex / Microsoft Foundry 同步供應。</p><hr><h2 id="benchmark-官方公布" tabindex="-1">Benchmark（官方公布） <a class="header-anchor" href="#benchmark-官方公布" aria-label="Permalink to &quot;Benchmark（官方公布）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Benchmark</th><th>結果</th></tr></thead><tbody><tr><td>Frontier-Bench v0.1</td><td>超越所有競品，為 Opus 4.8 的 <strong>2 倍</strong></td></tr><tr><td>CursorBench 3.2</td><td>與 Fable 5 差距 <strong>&lt; 0.5%</strong>，成本為其一半</td></tr><tr><td>ARC-AGI 3</td><td>次佳模型的 <strong>3 倍</strong></td></tr><tr><td>OSWorld 2.0</td><td>優於 Fable 5，成本為其 <strong>1/3</strong></td></tr></tbody></table><p>能力面重點：驗證與迭代解題能力增強（更常自查自糾）、agentic 推理與自我修正提升、視覺輸出品質提升、科學研究任務（有機化學、蛋白質分析）明顯改善。</p><p><strong>安全</strong>：官方稱其為近期模型中欺騙性行為比率最低者；攻擊性 cyber 能力仍低於 Mythos 5。</p><hr><h2 id="對本-workspace-的影響" tabindex="-1">對本 workspace 的影響 <a class="header-anchor" href="#對本-workspace-的影響" aria-label="Permalink to &quot;對本 workspace 的影響&quot;">​</a></h2><ul><li><strong>檔位對照</strong>：<code>ceiling</code> 檔位原 pin <code>claude-opus-4-8</code>，Opus 5 同價但全面更強 → 應評估換 pin（校準值 SSoT = <code>.claude/refs/model-profiles.md</code>，本檔不決定數字）。</li><li><strong>1M context</strong>：Opus 系列首次與 Sonnet 5 / Fable 5 同為 1M；先前以「Opus context 較小」為前提的 context 預算假設需重驗。</li><li><strong>Effort 可調</strong>：<code>low/medium/high</code> 讓「高檔位模型 + 低 effort」成為可行的成本策略——依 45-model-selection-guide.md，高檔位低 effort 有時在 per-task 經濟性上優於低檔位模型。</li><li><strong>Prompt cache</strong>：換模型會斷前綴快取，遵守 <code>context-management.md</code> 五禁令②（不 mid-session 換模型）。</li></ul><hr><h2 id="與同代模型選型對照" tabindex="-1">與同代模型選型對照 <a class="header-anchor" href="#與同代模型選型對照" aria-label="Permalink to &quot;與同代模型選型對照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情境</th><th>推薦模型</th></tr></thead><tbody><tr><td>日常主力、深推理、agentic 長跑</td><td><strong>Opus 5</strong></td></tr><tr><td>最難的 1% 問題、需最強能力且授權明確</td><td>Fable 5（$10/$50）</td></tr><tr><td>高頻 sub-agent、批次、成本敏感</td><td>Sonnet 5</td></tr><tr><td>極低成本 / 高頻分類</td><td>Haiku 4.5</td></tr><tr><td>受邀限定、無安全分類器</td><td>Mythos 5</td></tr></tbody></table><hr><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to &quot;延伸閱讀&quot;">​</a></h2><ul><li><code>45-model-selection-guide.md</code> — 官方選型框架（class × effort × 單位經濟）</li><li><code>41-claude-sonnet-5.md</code> — Sonnet 5（日常工作馬）</li><li><code>36-claude-fable-5.md</code> — Fable 5 / Mythos 5</li><li><code>48-w28-w31-features.md</code> — v2.1.219 等同批 Claude Code 變更</li></ul>',23)])])}const b=e(r,[["render",l]]);export{p as __pageData,b as default};
